/**
 * Arlo UI — Button
 *
 * Four appearances (solid · soft · ghost · outline) × three tones (primary · neutral · danger).
 * All main Button appearances use radii.full to match the Figma and WWW pill shape.
 * Visual sizes stay faithful to the design while sm/md expand to a ≥44pt touch target.
 *
 * **Preferred API:** `tone` + `appearance` + `children` as text label.
 *
 * **Legacy `variant`** (still supported):
 * - `primary` → tone primary + solid
 * - `secondary` → tone neutral + soft
 * - `ghost` → tone neutral + ghost
 * - `danger` → tone danger + solid
 *
 * Every visual decision lives in `buttonVariants` below — edit colors, sizes, and
 * spacing there in one place.
 */
import { forwardRef, useEffect, useMemo, useState } from 'react';
import {
  Animated,
  Easing,
  Platform,
  Pressable,
  StyleSheet,
  Text,
  View,
  type PressableProps,
  type StyleProp,
  type TextStyle,
  type ViewStyle,
} from 'react-native';
import Svg, { Path } from 'react-native-svg';
import { useTokens } from '../../foundation/theme-provider';
import { usePressFeedback, type ButtonHaptic } from './press-feedback';

type Tokens = ReturnType<typeof useTokens>;

export type ButtonTone = 'primary' | 'neutral' | 'danger';
export type ButtonAppearance = 'solid' | 'soft' | 'ghost' | 'outline';
export type ButtonSize = 'sm' | 'md' | 'lg' | 'xl';
export type { ButtonHaptic };

/** @deprecated Prefer `tone` + `appearance`. */
export type ButtonVariant = 'primary' | 'secondary' | 'ghost' | 'danger';

export type ButtonProps = Omit<PressableProps, 'style' | 'children'> & {
  children?: string;
  /** @deprecated Use `children` prop instead. */
  label?: string;
  /** @deprecated Maps to `tone` + `appearance`. When set, overrides `tone` and `appearance`. */
  variant?: ButtonVariant;
  tone?: ButtonTone;
  appearance?: ButtonAppearance;
  size?: ButtonSize;
  loading?: boolean;
  disabled?: boolean;
  leadingIcon?: React.ReactNode;
  trailingIcon?: React.ReactNode;
  /** Renders as a square (height × height) with icon centered. Requires `accessibilityLabel`. */
  iconOnly?: boolean;
  /** Render the label with the monospace family — useful for prices, codes. */
  mono?: boolean;
  fullWidth?: boolean;
  haptic?: ButtonHaptic;
  style?: StyleProp<ViewStyle>;
  labelStyle?: StyleProp<TextStyle>;
};

type Palette = { bg: string; fg: string; border: string; borderWidth: number };
type Dims = { minHeight: number; paddingX: number; type: { fontSize: number; lineHeight: number }; gap: number; iconSize: number };

/**
 * Single source of truth for the Button's looks. Each tone × appearance resolves to a
 * palette; each size resolves to its dimensions. Want a different primary fill or more
 * padding on `md`? It's all right here.
 */
function buttonVariants(t: Tokens): {
  tone: Record<ButtonTone, Record<ButtonAppearance, Palette>>;
  disabled: Record<ButtonAppearance, Palette>;
  size: Record<ButtonSize, Dims>;
} {
  const transparent = (fg: string): Palette => ({ bg: 'transparent', fg, border: 'transparent', borderWidth: 0 });
  return {
    tone: {
      primary: {
        solid: { bg: t.colors.interactivePrimary, fg: t.colors.textInteractivePrimary, border: 'transparent', borderWidth: 0 },
        soft: { bg: t.colors.feedbackInfoBg, fg: t.colors.interactivePrimary, border: 'transparent', borderWidth: 0 },
        ghost: transparent(t.colors.textInteractiveTertiary),
        outline: { bg: 'transparent', fg: t.colors.interactivePrimary, border: t.colors.borderPrimary, borderWidth: 1 },
      },
      neutral: {
        solid: { bg: t.colors.textSecondary, fg: t.colors.textInverse, border: 'transparent', borderWidth: 0 },
        soft: { bg: t.colors.surfaceInput, fg: t.colors.textPrimary, border: 'transparent', borderWidth: 0 },
        ghost: transparent(t.colors.textPrimary),
        outline: { bg: 'transparent', fg: t.colors.textPrimary, border: t.colors.borderPrimary, borderWidth: 1 },
      },
      danger: {
        solid: { bg: t.colors.feedbackError, fg: t.colors.textInteractivePrimary, border: 'transparent', borderWidth: 0 },
        soft: { bg: t.colors.feedbackErrorBg, fg: t.colors.textInteractiveError, border: 'transparent', borderWidth: 0 },
        ghost: transparent(t.colors.textInteractiveError),
        outline: { bg: 'transparent', fg: t.colors.feedbackError, border: t.colors.borderError, borderWidth: 1 },
      },
    },
    disabled: {
      solid: { bg: t.colors.interactiveDisabled, fg: t.colors.textTertiary, border: 'transparent', borderWidth: 0 },
      soft: { bg: t.colors.interactiveDisabled, fg: t.colors.textTertiary, border: 'transparent', borderWidth: 0 },
      ghost: transparent(t.colors.textTertiary),
      outline: { bg: 'transparent', fg: t.colors.textTertiary, border: t.colors.borderSecondary, borderWidth: 1 },
    },
    size: {
      sm: { minHeight: t.sizing.buttonHeight.sm, paddingX: t.spacing[3], type: t.typography.bodySm, gap: t.spacing[1], iconSize: t.sizing.icon.xs },
      md: { minHeight: t.sizing.buttonHeight.md, paddingX: t.spacing[4], type: t.typography.body, gap: t.spacing[2], iconSize: t.sizing.icon.sm },
      lg: { minHeight: t.sizing.buttonHeight.lg, paddingX: t.spacing[5], type: t.typography.title3, gap: t.spacing[2], iconSize: t.sizing.icon.sm },
      xl: { minHeight: t.sizing.buttonHeight.xl, paddingX: t.spacing[6], type: t.typography.title3, gap: t.spacing[3], iconSize: t.sizing.icon.md },
    },
  };
}

const LEGACY_VARIANT: Record<ButtonVariant, { tone: ButtonTone; appearance: ButtonAppearance }> = {
  primary: { tone: 'primary', appearance: 'solid' },
  secondary: { tone: 'neutral', appearance: 'soft' },
  ghost: { tone: 'neutral', appearance: 'ghost' },
  danger: { tone: 'danger', appearance: 'solid' },
};

function touchTargetInset(visualSize: number, minimumSize: number) {
  const inset = Math.max(0, Math.ceil((minimumSize - visualSize) / 2));
  return inset > 0 ? { top: inset, bottom: inset, left: inset, right: inset } : undefined;
}

function ButtonSpinner({
  color,
  size,
  reduceMotion,
}: {
  color: string;
  size: number;
  reduceMotion?: boolean;
}) {
  const t = useTokens();
  const [rotation] = useState(() => new Animated.Value(0));

  useEffect(() => {
    const animation = Animated.loop(
      Animated.timing(rotation, {
        toValue: 1,
        duration: reduceMotion ? t.motion.duration.slow * 4 : t.motion.duration.slow * 2,
        easing: Easing.linear,
        useNativeDriver: true,
      }),
    );
    animation.start();
    return () => animation.stop();
  }, [rotation, reduceMotion, t.motion.duration.slow]);

  return (
    <Animated.View
      accessibilityLabel="Loading"
      style={{
        width: size,
        height: size,
        transform: [
          {
            rotate: rotation.interpolate({
              inputRange: [0, 1],
              outputRange: ['0deg', '360deg'],
            }),
          },
        ],
      }}
    >
      <Svg width={size} height={size} viewBox="0 0 24 24" fill="none">
        <Path
          d="M21.75 12C21.75 14.5859 20.7228 17.0659 18.8943 18.8943C17.0658 20.7228 14.5859 21.75 12 21.75C9.41414 21.75 6.93419 20.7228 5.10571 18.8943C3.27723 17.0659 2.25 14.5859 2.25 12C2.25 8.1563 4.48219 4.6538 7.93688 3.06849C8.02638 3.02737 8.12311 3.00428 8.22153 3.00054C8.31996 2.9968 8.41816 3.01249 8.51052 3.0467C8.60289 3.08091 8.68761 3.13298 8.75985 3.19994C8.8321 3.26689 8.89044 3.34742 8.93156 3.43692C8.97268 3.52643 8.99577 3.62316 8.99951 3.72158C9.00325 3.82001 8.98756 3.91821 8.95335 4.01057C8.91914 4.10294 8.86707 4.18766 8.80011 4.2599C8.73316 4.33215 8.65263 4.39049 8.56312 4.43161C5.63906 5.77411 3.75 8.74411 3.75 12C3.75 14.1881 4.61919 16.2865 6.16637 17.8337C7.71354 19.3809 9.81196 20.25 12 20.25C14.188 20.25 16.2865 19.3809 17.8336 17.8337C19.3808 16.2865 20.25 14.1881 20.25 12C20.25 8.74411 18.3609 5.77411 15.4369 4.43161C15.2561 4.34857 15.1157 4.19711 15.0466 4.01057C14.9776 3.82403 14.9854 3.61769 15.0684 3.43692C15.1515 3.25616 15.3029 3.1158 15.4895 3.0467C15.676 2.9776 15.8824 2.98544 16.0631 3.06849C19.5178 4.6538 21.75 8.1563 21.75 12Z"
          fill={color}
        />
      </Svg>
    </Animated.View>
  );
}

export const Button = forwardRef<View, ButtonProps>(function Button(
  {
    children,
    label: labelProp,
    variant,
    tone: toneProp,
    appearance: appearanceProp,
    size = 'md',
    loading = false,
    disabled = false,
    leadingIcon,
    trailingIcon,
    iconOnly = false,
    mono = false,
    fullWidth = false,
    haptic = 'light',
    onPressIn,
    onPressOut,
    onFocus,
    onBlur,
    style,
    labelStyle,
    accessibilityLabel,
    ...rest
  },
  ref,
) {
  const t = useTokens();
  const variants = useMemo(() => buttonVariants(t), [t]);
  const { pressed, reduceMotion, animatedStyle, onPressIn: pressIn, onPressOut: pressOut } =
    usePressFeedback({ haptic, onPressIn, onPressOut });
  const [focused, setFocused] = useState(false);

  const { tone, appearance } = useMemo(() => {
    if (variant != null) return LEGACY_VARIANT[variant];
    return {
      tone: toneProp ?? 'primary',
      appearance: appearanceProp ?? 'solid',
    };
  }, [variant, toneProp, appearanceProp]);

  const text = children ?? labelProp ?? '';
  const isPressDisabled = disabled || loading;
  const useDisabledVisual = disabled && !loading;

  const palette = useDisabledVisual ? variants.disabled[appearance] : variants.tone[tone][appearance];
  const dims = variants.size[size];

  const hitSlop = useMemo(
    () => touchTargetInset(dims.minHeight, t.sizing.touchTarget.minimum),
    [dims.minHeight, t.sizing.touchTarget.minimum],
  );

  const ipx = dims.iconSize;
  const iconWrap = useMemo(
    () => ({ width: ipx, height: ipx, alignItems: 'center', justifyContent: 'center' }) as const,
    [ipx],
  );

  const cornerRadius = t.radii.full;

  const feedbackOverlayColor =
    appearance === 'outline' || appearance === 'ghost'
      ? t.colors.interactiveTertiaryPressed
      : t.colors.touchFeedbackMain;

  const showFeedbackOverlay = !disabled && pressed;

  const focusWebStyle = useMemo((): ViewStyle | undefined => {
    if (Platform.OS !== 'web' || !focused) return undefined;
    const ring = tone === 'danger' ? t.focusRing.error : t.focusRing.main;
    return { boxShadow: ring } as ViewStyle;
  }, [focused, t.focusRing, tone]);

  const a11yLabel = accessibilityLabel ?? (iconOnly ? undefined : text);

  return (
    <Pressable
      ref={ref}
      accessibilityRole="button"
      accessibilityLabel={a11yLabel}
      accessibilityState={{ disabled: isPressDisabled, busy: loading }}
      disabled={isPressDisabled}
      onPressIn={pressIn}
      onPressOut={pressOut}
      onFocus={(e) => { setFocused(true); onFocus?.(e); }}
      onBlur={(e) => { setFocused(false); onBlur?.(e); }}
      hitSlop={hitSlop}
      {...rest}
    >
      <Animated.View
        style={[
          {
            backgroundColor: palette.bg,
            borderColor: palette.border,
            borderWidth: palette.borderWidth,
            borderRadius: cornerRadius,
            minHeight: dims.minHeight,
            minWidth: iconOnly ? dims.minHeight : 64,
            width: iconOnly ? dims.minHeight : undefined,
            alignSelf: fullWidth ? 'stretch' : 'flex-start',
          },
          focusWebStyle,
          animatedStyle,
          style,
        ]}
      >
        {showFeedbackOverlay ? (
          <View
            pointerEvents="none"
            // `absoluteFill`, not `absoluteFillObject`: RN 0.86 dropped the latter.
            // It fails silently — the lookup is `undefined`, RN skips falsy entries in
            // a style array, and what's left defines no geometry, so the overlay
            // renders at zero size and press feedback just stops appearing.
            style={[StyleSheet.absoluteFill, { borderRadius: cornerRadius, backgroundColor: feedbackOverlayColor }]}
          />
        ) : null}
        <View
          style={{
            flexDirection: 'row',
            alignItems: 'center',
            justifyContent: 'center',
            gap: iconOnly ? 0 : dims.gap,
            minHeight: dims.minHeight,
            paddingHorizontal: iconOnly ? 0 : dims.paddingX,
            width: fullWidth ? '100%' : undefined,
          }}
        >
          {loading ? (
            <View style={iconWrap}>
              <ButtonSpinner color={palette.fg} size={ipx} reduceMotion={reduceMotion} />
            </View>
          ) : leadingIcon ? (
            <View style={iconWrap}>{leadingIcon}</View>
          ) : null}
          {!loading && !iconOnly ? (
            <Text
              numberOfLines={1}
              style={[
                {
                  color: palette.fg,
                  fontFamily: mono ? t.fontFamilies.mono : t.fontFamilies.sans,
                  fontSize: dims.type.fontSize,
                  lineHeight: dims.type.lineHeight,
                  fontWeight: t.fontWeights.semibold,
                },
                labelStyle,
              ]}
            >
              {text}
            </Text>
          ) : null}
          {!loading && !iconOnly && trailingIcon ? <View style={iconWrap}>{trailingIcon}</View> : null}
        </View>
      </Animated.View>
    </Pressable>
  );
});

/**
 * Arlo UI — GhostButton
 *
 * Chromeless action: no background container, no border, no horizontal padding.
 * Heights reflect text line-height only (sm/md: 24px, lg: 28px, xl: 40px).
 * The pressable area expands beyond the visible label to meet the minimum touch target.
 * Three tones (matching Button): primary (brand blue), neutral (grey text), danger (red text).
 *
 * Every visual decision lives in `ghostVariants` below.
 */
import { forwardRef, useMemo } from 'react';
import {
  ActivityIndicator,
  Animated,
  Pressable,
  Text,
  View,
  type PressableProps,
  type StyleProp,
  type TextStyle,
  type ViewStyle,
} from 'react-native';
import { useTokens } from '../../foundation/theme-provider';
import { usePressFeedback, type ButtonHaptic } from './press-feedback';

type Tokens = ReturnType<typeof useTokens>;

export type GhostButtonTone = 'primary' | 'neutral' | 'danger';
export type GhostButtonSize = 'sm' | 'md' | 'lg' | 'xl';

/** @deprecated Use `GhostButtonTone` (`destructive` is now `danger`). */
export type GhostButtonType = 'primary' | 'neutral' | 'destructive';

export type GhostButtonProps = Omit<PressableProps, 'style' | 'children'> & {
  children: string;
  tone?: GhostButtonTone;
  /** @deprecated Use `tone`. `destructive` maps to `danger`. */
  type?: GhostButtonType;
  size?: GhostButtonSize;
  loading?: boolean;
  disabled?: boolean;
  leadingIcon?: React.ReactNode;
  trailingIcon?: React.ReactNode;
  haptic?: ButtonHaptic;
  style?: StyleProp<ViewStyle>;
  labelStyle?: StyleProp<TextStyle>;
};

type ToneStyle = { fg: string; pressedBg: string };
type GhostDims = { height: number; type: { fontSize: number; lineHeight: number }; gap: number; iconSize: number };

/** Single source of truth for the GhostButton's looks. */
function ghostVariants(t: Tokens): {
  tone: Record<GhostButtonTone, ToneStyle>;
  size: Record<GhostButtonSize, GhostDims>;
  disabledFg: string;
} {
  return {
    tone: {
      primary: { fg: t.colors.textInteractiveTertiary, pressedBg: t.colors.touchFeedbackMain },
      neutral: { fg: t.colors.textPrimary, pressedBg: t.colors.touchFeedbackMain },
      danger: { fg: t.colors.feedbackError, pressedBg: t.colors.feedbackErrorBg },
    },
    size: {
      sm: { height: 24, type: t.typography.bodySm, gap: t.spacing[1], iconSize: t.sizing.icon.xs },
      md: { height: 24, type: t.typography.body, gap: t.spacing[2], iconSize: t.sizing.icon.sm },
      lg: { height: 28, type: t.typography.title3, gap: t.spacing[2], iconSize: t.sizing.icon.sm },
      xl: { height: 40, type: t.typography.title2, gap: t.spacing[3], iconSize: t.sizing.icon.md },
    },
    disabledFg: t.colors.textTertiary,
  };
}

const LEGACY_TONE: Record<GhostButtonType, GhostButtonTone> = {
  primary: 'primary',
  neutral: 'neutral',
  destructive: 'danger',
};

function touchTargetInset(visualSize: number, minimumSize: number) {
  const vertical = Math.max(0, Math.ceil((minimumSize - visualSize) / 2));
  return { top: vertical, bottom: vertical, left: 12, right: 12 };
}

export const GhostButton = forwardRef<View, GhostButtonProps>(function GhostButton(
  {
    children,
    tone: toneProp,
    type,
    size = 'md',
    loading = false,
    disabled = false,
    leadingIcon,
    trailingIcon,
    haptic = 'light',
    onPressIn,
    onPressOut,
    style,
    labelStyle,
    accessibilityLabel,
    ...rest
  },
  ref,
) {
  const t = useTokens();
  const variants = useMemo(() => ghostVariants(t), [t]);
  const { pressed, animatedStyle, onPressIn: pressIn, onPressOut: pressOut } = usePressFeedback({
    haptic,
    onPressIn,
    onPressOut,
  });

  const tone = toneProp ?? (type != null ? LEGACY_TONE[type] : 'neutral');
  const isPressDisabled = disabled || loading;
  const dims = variants.size[size];
  const hitSlop = useMemo(
    () => touchTargetInset(dims.height, t.sizing.touchTarget.minimum),
    [dims.height, t.sizing.touchTarget.minimum],
  );
  const textColor = disabled ? variants.disabledFg : variants.tone[tone].fg;
  const pressedBg = variants.tone[tone].pressedBg;

  const iconWrap = useMemo(
    () => ({ width: dims.iconSize, height: dims.iconSize, alignItems: 'center', justifyContent: 'center' }) as const,
    [dims.iconSize],
  );

  return (
    <Pressable
      ref={ref}
      accessibilityRole="button"
      accessibilityLabel={accessibilityLabel ?? children}
      accessibilityState={{ disabled: isPressDisabled, busy: loading }}
      disabled={isPressDisabled}
      onPressIn={pressIn}
      onPressOut={pressOut}
      hitSlop={hitSlop}
      {...rest}
    >
      <Animated.View
        style={[
          {
            flexDirection: 'row',
            alignItems: 'center',
            justifyContent: 'center',
            minHeight: dims.height,
            gap: dims.gap,
            borderRadius: t.radii.sm,
            backgroundColor: !disabled && pressed ? pressedBg : 'transparent',
          },
          animatedStyle,
          style,
        ]}
      >
        {loading ? (
          <View style={iconWrap}>
            <ActivityIndicator color={textColor} size="small" />
          </View>
        ) : leadingIcon ? (
          <View style={iconWrap}>{leadingIcon}</View>
        ) : null}
        {!loading ? (
          <Text
            numberOfLines={1}
            style={[
              {
                color: textColor,
                fontFamily: t.fontFamilies.sans,
                fontSize: dims.type.fontSize,
                lineHeight: dims.type.lineHeight,
                fontWeight: t.fontWeights.semibold,
              },
              labelStyle,
            ]}
          >
            {children}
          </Text>
        ) : null}
        {!loading && trailingIcon ? <View style={iconWrap}>{trailingIcon}</View> : null}
      </Animated.View>
    </Pressable>
  );
});

/**
 * Arlo UI — FAB (Floating Action Button)
 *
 * Circular, 48×48px, single icon. Primary or neutral tone.
 * Shadow on rest, no shadow on press. Reduced opacity (~28%) when disabled.
 * Export `FAB` is the canonical name; `FabButton` kept for backward compatibility.
 */
import { forwardRef, useMemo, useState, type ReactNode } from 'react';
import {
  Animated,
  Platform,
  Pressable,
  View,
  type PressableProps,
  type StyleProp,
  type ViewStyle,
} from 'react-native';
import { useTokens } from '../../foundation/theme-provider';
import { usePressFeedback, type ButtonHaptic } from './press-feedback';

type Tokens = ReturnType<typeof useTokens>;

export type FabTone = 'primary' | 'neutral';

/** Single source of truth for the FAB's rest/pressed background per tone. */
function fabVariants(t: Tokens): Record<FabTone, { rest: string; pressed: string }> {
  return {
    primary: { rest: t.colors.interactivePrimary, pressed: t.colors.interactivePrimaryPressed },
    neutral: { rest: t.colors.surfaceElevated, pressed: t.colors.interactiveSecondaryPressed },
  };
}

export type FABProps = Omit<PressableProps, 'style' | 'children'> & {
  icon: ReactNode;
  /** @deprecated Use `icon` prop instead. */
  children?: ReactNode;
  tone?: FabTone;
  disabled?: boolean;
  haptic?: ButtonHaptic;
  accessibilityLabel: string;
  style?: StyleProp<ViewStyle>;
};

/** @deprecated Use `FABProps`. */
export type FabButtonProps = FABProps;

const FAB_SIZE = 48;
const FAB_ICON_SIZE = 24;

export const FAB = forwardRef<View, FABProps>(function FAB(
  {
    icon,
    children,
    tone = 'primary',
    disabled = false,
    haptic = 'medium',
    accessibilityLabel,
    onPressIn,
    onPressOut,
    onFocus,
    onBlur,
    style,
    ...rest
  },
  ref,
) {
  const t = useTokens();
  const palette = useMemo(() => fabVariants(t)[tone], [t, tone]);
  const { pressed, animatedStyle, onPressIn: pressIn, onPressOut: pressOut } = usePressFeedback({
    haptic,
    onPressIn,
    onPressOut,
  });
  const [focused, setFocused] = useState(false);

  const content = icon ?? children;

  const shadow = useMemo(() => {
    if (disabled || pressed) return t.shadows.none as unknown as ViewStyle;
    return t.shadows.sm as unknown as ViewStyle;
  }, [disabled, pressed, t.shadows]);

  const focusOutline = useMemo((): ViewStyle | undefined => {
    if (Platform.OS !== 'web' || !focused || disabled) return undefined;
    return {
      outlineWidth: 2,
      outlineStyle: 'solid',
      outlineColor: t.colors.focusRingMain,
      outlineOffset: 4,
    } as ViewStyle;
  }, [disabled, focused, t.colors.focusRingMain]);

  const bg = pressed ? palette.pressed : palette.rest;

  return (
    <Pressable
      ref={ref}
      accessibilityRole="button"
      accessibilityLabel={accessibilityLabel}
      accessibilityState={{ disabled }}
      disabled={disabled}
      onPressIn={pressIn}
      onPressOut={pressOut}
      onFocus={(e) => { setFocused(true); onFocus?.(e); }}
      onBlur={(e) => { setFocused(false); onBlur?.(e); }}
      {...rest}
    >
      <Animated.View
        style={[
          {
            width: FAB_SIZE,
            height: FAB_SIZE,
            borderRadius: t.radii.full,
            backgroundColor: bg,
            alignItems: 'center',
            justifyContent: 'center',
            opacity: disabled ? 0.28 : 1,
          },
          shadow,
          focusOutline,
          animatedStyle,
          style,
        ]}
      >
        <View style={{ width: FAB_ICON_SIZE, height: FAB_ICON_SIZE, alignItems: 'center', justifyContent: 'center' }}>
          {content}
        </View>
      </Animated.View>
    </Pressable>
  );
});

/** @deprecated Use `FAB`. */
export const FabButton = FAB;

/**
 * Arlo UI — SocialAuthButton
 *
 * Fixed-label OAuth buttons for Google, Apple, Facebook, and X.
 * Two types: `fill` (brand background, white text) and `secondary` (outlined, brand icon, text-primary label).
 * Labels are not customizable per spec: "Sign in with {Platform}".
 */
import { forwardRef, useMemo, useState, type ReactNode } from 'react';
import {
  ActivityIndicator,
  Animated,
  Platform,
  Pressable,
  Text,
  View,
  type PressableProps,
  type StyleProp,
  type ViewStyle,
} from 'react-native';
import { useTokens } from '../../foundation/theme-provider';
import { usePressFeedback, type ButtonHaptic } from './press-feedback';

type Tokens = ReturnType<typeof useTokens>;

const BRAND_COLORS = {
  google: '#4285F4',
  apple: '#000000',
  facebook: '#1877F2',
  x: '#000000',
} as const;

const LABELS = {
  google: 'Sign in with Google',
  apple: 'Sign in with Apple',
  facebook: 'Sign in with Facebook',
  x: 'Sign in with X',
} as const;

export type SocialPlatform = 'google' | 'apple' | 'facebook' | 'x';
export type SocialAuthType = 'fill' | 'secondary';

/** @deprecated Use `SocialPlatform`. */
export type SocialAuthProvider = 'facebook' | 'x';

/** @deprecated Use `SocialAuthType`. */
export type SocialAuthAppearance = 'brandSolid' | 'brandSoft' | 'brandOutline' | 'neutralSolid' | 'neutralOutline';

type Size = 'sm' | 'md' | 'lg' | 'xl';

export type SocialAuthButtonProps = Omit<PressableProps, 'style' | 'children'> & {
  platform: SocialPlatform;
  /** @deprecated Use `platform`. */
  provider?: SocialAuthProvider;
  type?: SocialAuthType;
  /** @deprecated Use `type`. */
  appearance?: SocialAuthAppearance;
  size?: Size;
  loading?: boolean;
  disabled?: boolean;
  fullWidth?: boolean;
  haptic?: ButtonHaptic;
  /** Replace the default platform glyph (e.g. SVG asset). */
  renderLeading?: (color: string, iconPx: number) => ReactNode;
  style?: StyleProp<ViewStyle>;
};

type SocialPalette = { bg: string; fg: string; iconFg: string; border: string; borderWidth: number };
type SocialDims = { minHeight: number; paddingX: number; type: { fontSize: number; lineHeight: number }; gap: number; iconPx: number };

/**
 * Single source of truth for the SocialAuthButton's looks. The palette mixes the
 * per-platform brand color with the `fill`/`secondary` type; sizes are a flat map.
 */
function socialPalette(
  t: Tokens,
  platform: SocialPlatform,
  type: SocialAuthType,
  disabled: boolean,
): SocialPalette {
  if (disabled) {
    return { bg: t.colors.interactiveDisabled, fg: t.colors.textTertiary, iconFg: t.colors.textTertiary, border: 'transparent', borderWidth: 0 };
  }
  const brand = BRAND_COLORS[platform];
  if (type === 'fill') {
    return {
      bg: brand,
      fg: t.colors.textInteractivePrimary,
      iconFg: t.colors.textInteractivePrimary,
      border: 'transparent',
      borderWidth: 0,
    };
  }
  // secondary: outlined, brand icon, text-primary label
  return { bg: 'transparent', fg: t.colors.textPrimary, iconFg: brand, border: t.colors.borderPrimary, borderWidth: 1 };
}

function socialSizes(t: Tokens): Record<Size, SocialDims> {
  return {
    sm: { minHeight: t.sizing.buttonHeight.sm, paddingX: t.spacing[3], type: t.typography.bodySm, gap: t.spacing[1], iconPx: t.sizing.icon.xs },
    md: { minHeight: t.sizing.buttonHeight.md, paddingX: t.spacing[4], type: t.typography.body, gap: t.spacing[2], iconPx: t.sizing.icon.sm },
    lg: { minHeight: t.sizing.buttonHeight.lg, paddingX: t.spacing[5], type: t.typography.title3, gap: t.spacing[2], iconPx: t.sizing.icon.sm },
    xl: { minHeight: t.sizing.buttonHeight.xl, paddingX: t.spacing[6], type: t.typography.title3, gap: t.spacing[3], iconPx: t.sizing.icon.md },
  };
}

function touchTargetInset(visualSize: number, minimumSize: number) {
  const inset = Math.max(0, Math.ceil((minimumSize - visualSize) / 2));
  return inset > 0 ? { top: inset, bottom: inset, left: inset, right: inset } : undefined;
}

function mapLegacyAppearance(appearance: SocialAuthAppearance): SocialAuthType {
  return appearance === 'neutralOutline' ? 'secondary' : 'fill';
}

/**
 * Fallback brand letterforms, drawn in the system face on purpose — a brand mark
 * should not take on the app's typeface, and Apple's `` glyph exists only in the
 * system font. This is the one place `fontFamily` is intentionally not a token.
 */
function DefaultGlyph({ platform, color, iconPx }: { platform: SocialPlatform; color: string; iconPx: number }) {
  const fs = Math.round(iconPx * 0.62);
  switch (platform) {
    case 'google':
      return (
        <Text style={{ color, fontSize: fs, fontWeight: '700', fontFamily: 'System' }} allowFontScaling={false}>
          G
        </Text>
      );
    case 'apple':
      return (
        <Text style={{ color, fontSize: fs, fontWeight: '700', fontFamily: 'System' }} allowFontScaling={false}>

        </Text>
      );
    case 'facebook':
      return (
        <Text style={{ color, fontSize: fs, fontWeight: '700', fontFamily: 'System' }} allowFontScaling={false}>
          f
        </Text>
      );
    case 'x':
      return (
        <Text style={{ color, fontSize: Math.round(iconPx * 0.58), fontWeight: '900', fontFamily: 'System', letterSpacing: -0.5 }} allowFontScaling={false}>
          X
        </Text>
      );
  }
}

export const SocialAuthButton = forwardRef<View, SocialAuthButtonProps>(function SocialAuthButton(
  {
    platform: platformProp,
    provider,
    type: typeProp,
    appearance,
    size = 'md',
    loading = false,
    disabled = false,
    fullWidth = false,
    haptic = 'light',
    renderLeading,
    onPressIn,
    onPressOut,
    onFocus,
    onBlur,
    style,
    ...rest
  },
  ref,
) {
  const t = useTokens();
  const { animatedStyle, onPressIn: pressIn, onPressOut: pressOut } = usePressFeedback({
    haptic,
    onPressIn,
    onPressOut,
  });
  const [focused, setFocused] = useState(false);

  const platform = platformProp ?? (provider as SocialPlatform) ?? 'google';
  const type: SocialAuthType = typeProp ?? (appearance ? mapLegacyAppearance(appearance) : 'fill');

  const isPressDisabled = disabled || loading;
  const useDisabledVisual = disabled && !loading;

  const palette = useMemo(
    () => socialPalette(t, platform, type, useDisabledVisual),
    [t, platform, type, useDisabledVisual],
  );

  const dims = useMemo(() => socialSizes(t)[size], [size, t]);
  const hitSlop = useMemo(
    () => touchTargetInset(dims.minHeight, t.sizing.touchTarget.minimum),
    [dims.minHeight, t.sizing.touchTarget.minimum],
  );

  const iconWrap = useMemo(
    () => ({ width: dims.iconPx, height: dims.iconPx, alignItems: 'center', justifyContent: 'center' }) as const,
    [dims.iconPx],
  );

  const focusWebStyle = useMemo((): ViewStyle | undefined => {
    if (Platform.OS !== 'web' || !focused) return undefined;
    return { boxShadow: t.focusRing.main } as ViewStyle;
  }, [focused, t.focusRing.main]);

  const label = LABELS[platform];

  return (
    <Pressable
      ref={ref}
      accessibilityRole="button"
      accessibilityLabel={label}
      accessibilityState={{ disabled: isPressDisabled, busy: loading }}
      disabled={isPressDisabled}
      onPressIn={pressIn}
      onPressOut={pressOut}
      onFocus={(e) => { setFocused(true); onFocus?.(e); }}
      onBlur={(e) => { setFocused(false); onBlur?.(e); }}
      hitSlop={hitSlop}
      {...rest}
    >
      <Animated.View
        style={[
          {
            backgroundColor: palette.bg,
            borderColor: palette.border,
            borderWidth: palette.borderWidth,
            borderRadius: t.radii.full,
            minHeight: dims.minHeight,
            minWidth: t.spacing[16],
            paddingHorizontal: dims.paddingX,
            flexDirection: 'row',
            alignItems: 'center',
            justifyContent: 'center',
            gap: dims.gap,
            alignSelf: fullWidth ? 'stretch' : 'flex-start',
          },
          focusWebStyle,
          animatedStyle,
          style,
        ]}
      >
        <View style={iconWrap}>
          {loading ? (
            <ActivityIndicator color={palette.iconFg} size="small" />
          ) : renderLeading ? (
            renderLeading(palette.iconFg, dims.iconPx)
          ) : (
            <DefaultGlyph platform={platform} color={palette.iconFg} iconPx={dims.iconPx} />
          )}
        </View>
        {!loading ? (
          <Text
            numberOfLines={1}
            style={{
              color: palette.fg,
              fontFamily: t.fontFamilies.sans,
              fontSize: dims.type.fontSize,
              lineHeight: dims.type.lineHeight,
              fontWeight: t.fontWeights.semibold,
            }}
          >
            {label}
          </Text>
        ) : null}
      </Animated.View>
    </Pressable>
  );
});

/**
 * Arlo UI — shared button-family interaction primitives.
 *
 * The whole button family (Button, GhostButton, FAB, SocialAuthButton) shares the
 * same press feel: a spring-eased scale-down on press (opacity fade when "reduce
 * motion" is on) plus an optional haptic tap. Keeping it here means the timing,
 * easing, and accessibility behaviour live in exactly one place.
 */
import { useCallback, useEffect, useMemo, useState } from 'react';
import {
  AccessibilityInfo,
  Animated,
  Easing,
  type GestureResponderEvent,
} from 'react-native';
import { haptic as triggerHaptic } from '../../foundation/haptics';
import { useTokens } from '../../foundation/theme-provider';

export type ButtonHaptic = 'light' | 'medium' | 'none';

/** Tracks the OS "reduce motion" accessibility setting. */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    let mounted = true;
    AccessibilityInfo.isReduceMotionEnabled?.().then((value: boolean) => {
      if (mounted) setReduced(value);
    });
    const sub = AccessibilityInfo.addEventListener('reduceMotionChanged', (value: boolean) => {
      setReduced(value);
    });
    return () => {
      mounted = false;
      sub?.remove?.();
    };
  }, []);
  return reduced;
}

type PressFeedbackOptions = {
  haptic?: ButtonHaptic;
  onPressIn?: ((e: GestureResponderEvent) => void) | null;
  onPressOut?: ((e: GestureResponderEvent) => void) | null;
};

/**
 * Press-driven animation + haptic for the button family.
 *
 * Returns `pressed` (for press overlays), the `animatedStyle` to spread onto the
 * animated container, `reduceMotion`, and the `onPressIn`/`onPressOut` handlers to
 * pass straight to the `Pressable`.
 */
export function usePressFeedback({ haptic = 'light', onPressIn, onPressOut }: PressFeedbackOptions) {
  const { motion } = useTokens();
  const [press] = useState(() => new Animated.Value(0));
  const [pressed, setPressed] = useState(false);
  const reduceMotion = useReducedMotion();

  // Curve and duration come straight from the motion tokens (easeOut · instant).
  const easing = useMemo(() => {
    const [x1, y1, x2, y2] = motion.easing.easeOut;
    return Easing.bezier(x1, y1, x2, y2);
  }, [motion.easing.easeOut]);
  const duration = motion.duration.instant;

  const handlePressIn = useCallback(
    (e: GestureResponderEvent) => {
      setPressed(true);
      if (haptic !== 'none') void triggerHaptic(haptic);
      Animated.timing(press, {
        toValue: 1,
        duration,
        easing,
        useNativeDriver: true,
      }).start();
      onPressIn?.(e);
    },
    // `setPressed` is a stable setter and needs no listing — except that esbuild
    // renames the `useState` import when bundling for Snack, which defeats the
    // exhaustive-deps stability check and warns in their editor. Listing it is a
    // runtime no-op.
    [haptic, onPressIn, press, duration, easing, setPressed],
  );

  const handlePressOut = useCallback(
    (e: GestureResponderEvent) => {
      setPressed(false);
      Animated.timing(press, {
        toValue: 0,
        duration,
        easing,
        useNativeDriver: true,
      }).start();
      onPressOut?.(e);
    },
    [onPressOut, press, duration, easing, setPressed],
  );

  const animatedStyle = reduceMotion
    ? { opacity: press.interpolate({ inputRange: [0, 1], outputRange: [1, motion.pressed.opacity] }) }
    : { transform: [{ scale: press.interpolate({ inputRange: [0, 1], outputRange: [1, motion.pressed.scale] }) }] };

  return {
    pressed,
    reduceMotion,
    animatedStyle,
    onPressIn: handlePressIn,
    onPressOut: handlePressOut,
  };
}

